package io.github.ericonyu.qimen4java;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class QimenTest{@Test void smoke()throws Exception{Map<String,Object> r=Qimen.calculate(Map.of("year",2026,"month",4,"day",10,"hour",14,"minute",30,"timezone","Asia/Shanghai"));assertEquals(9,((List<?>)r.get("palaces")).size());}@Test void lateZi()throws Exception{Map<String,Object>a=Qimen.calculate(new HashMap<>(Map.of("year",2026,"month",4,"day",10,"hour",23,"minute",30,"timezone","Asia/Shanghai"))),b=Qimen.calculate(new HashMap<>(Map.of("year",2026,"month",4,"day",11,"hour",0,"minute",30,"timezone","Asia/Shanghai")));assertEquals(a.get("siZhu"),b.get("siZhu"));}}
